# AI: below section was generated by an AI
# PlatformIO library build script of the home_gadgets usermod (see "extraScript" in library.json).
# Compresses home.htm with gzip into home_page_gz.h before the usermod is compiled, the same way
# WLED serves its own pages gzipped. The header is written to the build directory, so no generated
# file ends up in the source tree. Leading indentation and empty lines are removed first; this is
# safe for home.htm because it contains no <pre> blocks and no multi-line template strings.
Import("env")
import gzip
import hashlib
import inspect
import os

here = os.path.dirname(os.path.abspath(inspect.getframeinfo(inspect.currentframe()).filename))
src = os.path.join(here, "home.htm")
out_dir = os.path.join(env.subst("$BUILD_DIR"), "home_gadgets_gen")
out = os.path.join(out_dir, "home_page_gz.h")

with open(src, "r", encoding="utf-8") as f:
    html = "\n".join(line.lstrip(" \t") for line in f.read().splitlines() if line.strip())
data = gzip.compress(html.encode("utf-8"), compresslevel=9, mtime=0)
etag = hashlib.sha1(data).hexdigest()[:12]

lines = [
    "// generated by gen_page.py from home.htm - do not edit",
    "#pragma once",
    '#define HOME_PAGE_ETAG "\\"hg-%s\\""' % etag,
    "static const uint8_t HOME_PAGE_GZ[] PROGMEM = {",
]
for i in range(0, len(data), 20):
    lines.append("  " + ",".join("0x%02x" % b for b in data[i:i + 20]) + ",")
lines.append("};")
text = "\n".join(lines) + "\n"

os.makedirs(out_dir, exist_ok=True)
old = None
if os.path.exists(out):
    with open(out, "r", encoding="utf-8") as f:
        old = f.read()
if old != text:  # only rewrite when the page changed, to avoid needless recompiles
    with open(out, "w", encoding="utf-8") as f:
        f.write(text)
    print("home_gadgets: page %d bytes, gzipped %d bytes" % (len(html), len(data)))

env.Append(CPPPATH=[out_dir])
# AI: end
